package com.orderflow.delivery.messaging;import com.fasterxml.jackson.databind.ObjectMapper;import com.orderflow.delivery.service.DeliveryWorkflowService;import com.orderflow.events.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.messaging.handler.annotation.Header;import org.springframework.stereotype.Component;
@Component public class OrderEventListener{private final ObjectMapper mapper;private final DeliveryWorkflowService workflow;public OrderEventListener(ObjectMapper m,DeliveryWorkflowService w){mapper=m;workflow=w;}@KafkaListener(topics="${app.kafka.topics.delivery-events}",groupId="delivery-service-order-events-v1")public void consume(String payload,@Header("eventType")String type)throws Exception{switch(EventType.valueOf(type)){case DELIVERY_REQUESTED->workflow.requested(mapper.readValue(payload,DeliveryRequestedEvent.class));case DELIVERY_CANCEL_REQUESTED->workflow.cancel(mapper.readValue(payload,DeliveryCancelRequestedEvent.class));default->{ }}}}
